<?php
namespace Modules\DealerManagement\Http\Controllers\Portal;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Modules\DealerManagement\Services\DealerContext;
class RoleController extends Controller {
 public function index(){ $u=app(DealerContext::class)->user(); abort_unless((int)$u->is_dealer_admin===1,403); $roles=DB::table('dlr_roles')->where('dealer_id',$u->dealer_id)->orderBy('name')->get(); $permissions=require __DIR__.'/../../../Config/permissions.php'; $roleIds=$roles->pluck('id')->all(); $byRole=empty($roleIds)?collect():DB::table('dlr_role_permissions')->whereIn('role_id',$roleIds)->get(['role_id','permission_key'])->groupBy('role_id'); foreach($roles as $role){$role->permissions=($byRole->get($role->id)?:collect())->pluck('permission_key')->all();} return view('dealermanagement::users.roles',compact('roles','permissions')); }
 public function store(Request $r){ $u=app(DealerContext::class)->user(); abort_unless((int)$u->is_dealer_admin===1,403); $d=$r->validate(['name'=>'required|string|max:100','permissions'=>'array','permissions.*'=>'string','notes'=>'nullable|string']); DB::transaction(function() use($u,$d){$now=now();$id=DB::table('dlr_roles')->insertGetId(['business_id'=>$u->business_id,'dealer_id'=>$u->dealer_id,'name'=>$d['name'],'is_system'=>0,'notes'=>$d['notes']??null,'created_at'=>$now,'updated_at'=>$now]); $allowed=array_keys(require __DIR__.'/../../../Config/permissions.php'); $rows=[]; foreach(array_intersect($d['permissions']??[],$allowed) as $p)$rows[]=['role_id'=>$id,'permission_key'=>$p,'created_at'=>$now,'updated_at'=>$now]; if($rows)DB::table('dlr_role_permissions')->insert($rows);}); return back()->with('status','Role created.'); }
}
